--
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS parking_session (
    session_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    vehicle_id BIGINT NOT NULL,
    zone_id BIGINT NOT NULL,
    booking_reference VARCHAR(255) NULL,
    exit_time DATETIME NULL,
